scores = ["A", "A", "B", "B", "F", "F", "B", "A", "B", "F"]

score_dict = {}
for score in scores:
    if score in score_dict:
        score_dict[score] += 1
    else:
        score_dict[score] = 1
for score, count in score_dict.items():
    print("{}有{}个".format(score, count))

